'use strict';

// Builds the three shipped artefacts from src/.
//
//   index.js            CommonJS, at the package root so that `main` never
//                       moves and require('country-list-js/index.js') keeps
//                       working.  The data files are NOT inlined: the require
//                       calls survive verbatim and resolve against data/,
//                       which is the only copy and the one deep-importers read.
//
//   dist/index.mjs      ESM.  A thin re-export of the CommonJS build rather
//                       than a second bundle: bundling it again would put a
//                       third copy of the data in the tarball, and would give
//                       an application that used both `require` and `import`
//                       two separate runtimes with two separate caches.
//
//   dist/country.min.js Minified IIFE for browsers and CDNs, assigning
//                       window.country.  Same filename as 3.1.8 shipped:
//                       those URLs are pinned in other people's HTML.

const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');

const root = path.join(__dirname, '..');
const entry = path.join(root, 'src', 'index.ts');

// esbuild leaves external specifiers untouched, so './data/x.json' written in
// the source arrives verbatim in an output file that sits beside data/
const DATA = ['./data/countries.json', './data/provinces.json',
              './data/retired-currencies.json', './data/name-aliases.json'];

// the module's value is its default export; flatten it so that
// require('country-list-js') is the object itself, with no default or
// __esModule key alongside the thirteen real ones
const FLATTEN_CJS = 'module.exports = module.exports.default;';

// For the bundled outputs the same './data/x.json' specifiers have to resolve
// to the real files, which sit at the package root rather than beside src/.
const resolveData = {
    name: 'data',
    setup(build) {
        build.onResolve({filter: /^\.\/data\/.*\.json$/}, args => ({
            path: path.join(root, args.path),
        }));
    },
};

const common = {entryPoints: [entry], bundle: true, target: 'es2019', logLevel: 'warning'};

const builds = [];

builds.push(esbuild.build({
    ...common,
    format: 'cjs',
    platform: 'node',
    outfile: path.join(root, 'index.js'),
    external: DATA,
    footer: {js: FLATTEN_CJS},
}));



builds.push(esbuild.build({
    ...common,
    format: 'iife',
    platform: 'browser',
    globalName: 'country',
    outfile: path.join(root, 'dist', 'country.min.js'),
    minify: true,
    plugins: [resolveData],
    // the IIFE assigns the module namespace; unwrap it so a plain
    // <script> tag leaves `country` as the module object, which is what
    // the README has always told people to expect
    footer: {js: 'country = country.default;'},
}));

// The root index.d.ts is a re-export of the emitted declarations, so that
// `main` and `types` sit beside each other at the package root the way they
// have since 1.0.
const ROOT_DTS = [
    '// Generated by scripts/build-bundles.js.  Do not edit.',
    "export * from './dist/types/index';",
    "export { default } from './dist/types/index';",
    "export { default as country } from './dist/types/index';",
    '',
].join('\n');

// Named ESM exports, so `import {findByIso2} from 'country-list-js'` works.
// Listed rather than derived: the set of exports is the public surface, and it
// should change only when someone edits this line.
const MEMBERS = ['all', 'cache', 'findByIso2', 'findByIso3', 'findByName',
                 'findByCapital', 'findByCurrency', 'findByProvince',
                 'findByPhoneNbr', 'ls', 'continents', 'names', 'capitals'];

const ESM = [
    '// Generated by scripts/build-bundles.js.  Do not edit.',
    '//',
    '// One runtime, not two: this re-exports the CommonJS build rather than',
    '// bundling a second copy.  `all` and `cache` are shared mutable state, so',
    '// an application using both require() and import() must see one of each.',
    "import country from '../index.js';",
    '',
    'export default country;',
    ...MEMBERS.map(m => 'export const ' + m + ' = country.' + m + ';'),
    '',
].join('\n');

Promise.all(builds).then(() => {
    fs.writeFileSync(path.join(root, 'index.d.ts'), ROOT_DTS);
    fs.writeFileSync(path.join(root, 'dist', 'index.mjs'), ESM);
    const kb = p => (fs.statSync(path.join(root, p)).size / 1024).toFixed(1) + ' KB';
    for (const p of ['index.js', 'dist/index.mjs', 'dist/country.min.js'])
        console.error('  %s %s', p.padEnd(22), kb(p));
}, e => { console.error(e.message); process.exit(1); });
